import math

def count_divisors(n):
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d(n):
    # d(n) is the number of positive divisors of n other than 1 and itself.
    # This is max(0, tau(n) - 2).
    if n == 1:
        return 0 # Divisors of 1: {1}. Divisors other than 1 and itself: {} -> 0
    tau_n = count_divisors(n)
    return max(0, tau_n - 2)

results = []
limit = 150
offset = 735

for n in range(1, limit + 1):
    dn = d(n)
    dn_plus_735 = d(n + offset)

    if dn == dn_plus_735:
        a = dn
        results.append((n, a))

print(results)
